-- 0062 — Shared watch folders (roadmap P4 item J, spec §4.1; admin spec §1.1–1.2).
--
-- A share is a 256-bit token generated by the server action (crypto.randomBytes(32).toString("base64url"),
-- 43 chars), stored as is (the owner needs to copy it again; it only opens what the owner chose to make
-- public). Revoke = delete, rotate = new token. The public page reads through shared_folder_view(token), which
-- returns only the fields the owner enabled and never an email, user id, watch id, folder id, channels,
-- conditions, engine state or alert history.
--
-- Also: reserved category slugs re-created from 0010 with the new top-level routes ('shared', 'seller',
-- 'deal-score'), and the two admin moderation RPCs.

create table if not exists public.watch_folder_shares (
  id           uuid primary key default gen_random_uuid(),
  folder_id    uuid not null unique references public.watch_folders(id) on delete cascade,
  user_id      uuid not null references public.users(id) on delete cascade,
  token        text not null unique check (token ~ '^[A-Za-z0-9_-]{43}$'),
  title        text check (title is null or char_length(btrim(title)) between 1 and 60),
  display_name text check (display_name is null or char_length(btrim(display_name)) between 1 and 40),
  show_prices  boolean not null default true,
  show_target  boolean not null default false,
  show_notes   boolean not null default false,
  include_done boolean not null default false,
  created_at   timestamptz not null default now(),
  updated_at   timestamptz not null default now()
);
create index if not exists idx_watch_folder_shares_user on public.watch_folder_shares (user_id);

-- A share may only point at one of its owner's folders (like watches_check_folder).
create or replace function public.watch_folder_shares_check()
returns trigger language plpgsql set search_path = public as $$
begin
  if not exists (select 1 from watch_folders f where f.id = new.folder_id and f.user_id = new.user_id) then
    raise exception 'Thư mục không hợp lệ.' using errcode = 'check_violation';
  end if;
  if tg_op = 'UPDATE' then
    if (new.title, new.display_name, new.show_prices, new.show_target, new.show_notes, new.include_done, new.token)
       is distinct from
       (old.title, old.display_name, old.show_prices, old.show_target, old.show_notes, old.include_done, old.token) then
      new.updated_at := now();
    end if;
  end if;
  return new;
end $$;
revoke execute on function public.watch_folder_shares_check() from public, anon, authenticated;
drop trigger if exists watch_folder_shares_check on public.watch_folder_shares;
create trigger watch_folder_shares_check before insert or update on public.watch_folder_shares
  for each row execute function public.watch_folder_shares_check();

-- Owner reads, edits the display settings and stops sharing. Insert and token rotation go through the
-- admin client in the server action (the token is never chosen by the browser).
alter table public.watch_folder_shares enable row level security;
drop policy if exists "folder_shares_owner_select" on public.watch_folder_shares;
create policy "folder_shares_owner_select" on public.watch_folder_shares
  for select to authenticated using ((select auth.uid()) = user_id);
drop policy if exists "folder_shares_owner_update" on public.watch_folder_shares;
create policy "folder_shares_owner_update" on public.watch_folder_shares
  for update to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
drop policy if exists "folder_shares_owner_delete" on public.watch_folder_shares;
create policy "folder_shares_owner_delete" on public.watch_folder_shares
  for delete to authenticated using ((select auth.uid()) = user_id);
revoke all on public.watch_folder_shares from anon, authenticated;
grant select, delete on public.watch_folder_shares to authenticated;
grant update (title, display_name, show_prices, show_target, show_notes, include_done)
  on public.watch_folder_shares to authenticated;

-- 100 = SHARED_FOLDER_MAX_ITEMS (src/lib/share-folder/constants.ts).
create or replace function public.shared_folder_view(p_token text)
returns jsonb
language sql stable security definer set search_path = public as $$
  with s as (
    select sh.*, f.name as folder_name
    from watch_folder_shares sh
    join watch_folders f on f.id = sh.folder_id
    join users u on u.id = sh.user_id
    where p_token ~ '^[A-Za-z0-9_-]{43}$'
      and sh.token = p_token
      and u.deleted_at is null
  ),
  items as (
    select w.created_at as w_created, w.updated_at as w_updated,
           jsonb_build_object(
             'product_name', p.canonical_name,
             'product_slug', p.slug,
             'category_slug', coalesce(c.slug, 'san-pham'),
             'image', p.image,
             'variant_id', w.variant_id,
             'variant_key', v.variant_key,
             'status', w.status,
             'price',       case when s.show_prices then vcp.price end,
             'in_stock',    case when s.show_prices then vcp.in_stock end,
             'observed_at', case when s.show_prices then vcp.observed_at end,
             'score',          case when s.show_prices and ds.price_at_compute = vcp.price then ds.score end,
             'recommendation', case when s.show_prices and ds.price_at_compute = vcp.price then ds.recommendation end,
             'target_price', case when s.show_target then w.target_price end,
             'note',         case when s.show_notes then w.note end
           ) as item
    from s
    join watches w on w.folder_id = s.folder_id and w.user_id = s.user_id
    join product_variants v on v.id = w.variant_id
    join products p on p.id = v.product_id
    left join categories c on c.id = p.category_id
    left join variant_current_price vcp on vcp.variant_id = w.variant_id
    left join variant_deal_scores ds on ds.variant_id = w.variant_id
    where w.status in ('active','paused') or (w.status = 'done' and s.include_done)
    order by w.created_at, w.id
    limit 100
  )
  select jsonb_build_object(
           'title', coalesce(s.title, s.folder_name),
           'display_name', s.display_name,
           'updated_at', greatest(s.updated_at, (select max(i.w_updated) from items i)),
           'show_prices', s.show_prices,
           'show_target', s.show_target,
           'show_notes', s.show_notes,
           'items', coalesce((select jsonb_agg(i.item order by i.w_created) from items i), '[]'::jsonb))
  from s
$$;
revoke execute on function public.shared_folder_view(text) from public;
grant execute on function public.shared_folder_view(text) to anon, authenticated, service_role;

-- ============================================================================
-- Reserved category slugs: 0010 list + the P2/P4 top-level routes. Fails loudly (with the slug) if a category
-- already uses one, instead of a bare constraint error.
-- ============================================================================
do $$
declare v_slug text;
begin
  select slug into v_slug from public.categories where slug in ('shared','seller','deal-score') limit 1;
  if v_slug is not null then
    raise exception 'category slug "%" collides with a reserved route; rename the category first', v_slug;
  end if;
end $$;
alter table public.categories drop constraint if exists categories_slug_reserved;
alter table public.categories add constraint categories_slug_reserved check (
  slug not in ('tim-kiem','brand','danh-muc','go','api','share-target','admin','auth','watch',
               'tai-khoan','account','login','register','search','privacy','terms','unsubscribe',
               'forgot-password','reset-password','sitemap.xml','robots.txt',
               'shared','seller','deal-score')
);

-- ============================================================================
-- Admin moderation (admin spec §1): who owns a link is never returned — no user id, email, token or note.
-- ============================================================================
create or replace function public.admin_folder_shares(p_q text default null, p_limit integer default 50,
                                                      p_offset integer default 0)
returns table (share_id uuid, title text, display_name text, folder_name text, item_count integer,
               owner_pending_deletion boolean, created_at timestamptz, updated_at timestamptz, total_count bigint)
language plpgsql stable security definer set search_path = public as $$
declare
  v_q      text := nullif(btrim(coalesce(p_q, '')), '');
  v_limit  integer := least(greatest(coalesce(p_limit, 50), 1), 100);
  v_offset integer := least(greatest(coalesce(p_offset, 0), 0), 100000);
begin
  if v_q is not null and char_length(v_q) > 100 then
    raise exception 'admin_folder_shares: từ khóa quá dài';
  end if;
  return query
    with base as (
      select s.id, coalesce(s.title, f.name) as title, s.display_name, f.name as folder_name,
             (select count(*)::integer from watches w
              where w.folder_id = s.folder_id and w.user_id = s.user_id
                and (w.status in ('active','paused') or (w.status = 'done' and s.include_done))) as item_count,
             (u.deleted_at is not null) as pending, s.created_at, s.updated_at
      from watch_folder_shares s
      join watch_folders f on f.id = s.folder_id
      join users u on u.id = s.user_id
      where v_q is null
         or f_unaccent(lower(coalesce(s.title, f.name) || ' ' || coalesce(s.display_name, '')))
            like '%' || f_unaccent(lower(v_q)) || '%'
    )
    select b.id, b.title, b.display_name, b.folder_name, b.item_count, b.pending, b.created_at, b.updated_at,
           count(*) over ()
    from base b
    order by b.updated_at desc, b.id
    limit v_limit offset v_offset;
end $$;

create or replace function public.admin_revoke_folder_share(p_share_id uuid, p_note text default null)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_note text := nullif(btrim(coalesce(p_note, '')), '');
  v_row  watch_folder_shares%rowtype;
  v_title text;
begin
  if v_note is not null and char_length(v_note) > 500 then
    raise exception 'admin_revoke_folder_share: ghi chú quá dài';
  end if;
  select s.* into v_row from watch_folder_shares s where s.id = p_share_id for update;
  if not found then
    return jsonb_build_object('revoked', false);
  end if;
  select coalesce(v_row.title, f.name) into v_title from watch_folders f where f.id = v_row.folder_id;
  delete from watch_folder_shares where id = p_share_id;
  perform admin_log('folder_share.revoke', 'folder_share', p_share_id::text,
                    jsonb_build_object('title', v_title, 'display_name', v_row.display_name,
                                       'created_at', v_row.created_at),
                    null, v_note);
  return jsonb_build_object('revoked', true);
end $$;

revoke execute on function public.admin_folder_shares(text, integer, integer),
                           public.admin_revoke_folder_share(uuid, text)
  from public, anon, authenticated;
grant execute on function public.admin_folder_shares(text, integer, integer),
                          public.admin_revoke_folder_share(uuid, text)
  to service_role;
